      <p>
        Claimed total: <strong data-testid="rollup-claimed-total">{sumAmounts(claims.data ?? [], held)}</strong>
      </p>
      {claims.isError && (
        <p data-testid="claims-error" role="alert">
          {claims.error.message}
        </p>
      )}
    </section>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 10, Component: ClaimsHead }),
  PersonCells.fill({ order: 10, Component: ClaimsCells }),
  SheetBody.fill({ order: 20, Component: ClaimedTotal }),
];
import { useMutationState } from '@tanstack/react-query';

/** The key every action on a person's row (a statement, a retirement) runs its mutation under, so the row shows
 *  one error at a time: the last action's. */
export const personActionKey = (sheetId: string, personId: number) => ['sheet', sheetId, 'person-action', personId] as const;

/** Whether the mutation (run under personActionKey) is the last action taken on the person's row: only that
 *  one's refusal shows, so the next action on the row removes the error of the one before. */
export function useLastPersonAction(sheetId: string, personId: number, submittedAt: number): boolean {
  const times = useMutationState({
    filters: { mutationKey: personActionKey(sheetId, personId) },
    select: (m) => m.state.submittedAt,
  });
  return submittedAt === Math.max(0, ...times);
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request: the reason, and the HTTP status (409: someone else saved the record first). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    // A refusal carries {"error": "<why>"}; show that, else the status line.
    const body = (await res.json().catch(() => null)) as { error?: string } | null;
    throw new HttpError(body?.error ?? `${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

/**
 * Runs a form's mutation, ignoring a second submit while the first has not answered (a double
 * click), so one submit stores one record. The guard is a ref, set synchronously, because a
 * second click can land before `isPending` has re-rendered the button disabled.
 */
export function useSubmitOnce<V>(mutation: UseMutationResult<unknown, Error, V, unknown>) {
  const inFlight = useRef(false);
  return (vars: V) => {
    if (inFlight.current) return;
    inFlight.current = true;
    mutation
      .mutateAsync(vars)
      .catch(() => {
        // the refusal is shown from the mutation's own error state
      })
      .finally(() => {
        inFlight.current = false;
      });
  };
}

